// Count spans by service ID
fetch spans, from:-1h
| filter isNotNull(dt.smartscape.service)
| summarize {span_count = count()}, by: {dt.smartscape.service}
| sort span_count desc
| limit 20

// Count spans by kind to understand your traffic patterns
fetch spans, from:-1h
| summarize {span_count = count()}, by: {span.kind}
| sort span_count desc

// Find all spans for a specific trace ID
// Replace YOUR_TRACE_ID with an actual trace.id from above
fetch spans, from:-1h
// trace.id is a uid: keep the toUid() wrapper — a plain string never matches.
// | filter trace.id == toUid("YOUR_TRACE_ID")
| fields start_time, span.id, span.parent_id, span.name, dt.service.name, duration
| sort start_time asc
| limit 100

// Summarize HTTP status codes by route
fetch spans, from:-1h
| filter isNotNull(http.response.status_code)
| summarize {status_count = count()}, by: {http.response.status_code}
| sort http.response.status_code asc

// Summarize gRPC calls by service and method.
//
// Use matchesValue() rather than == on rpc.system. matchesValue() is an exact but
// CASE-INSENSITIVE match, and real tenants carry more than one spelling: on the
// validation tenant both `grpc` (110,097 spans/hr) and `gRPC` (8,391 spans/hr) are
// present, because the value is whatever the instrumentation set. So
// `rpc.system == "grpc"` silently drops ~7% of gRPC traffic — a wrong number, not an
// error. Live-verified 07/30/2026: matchesValue returns 118,393 spans across both.
fetch spans, from:-1h
| filter matchesValue(rpc.system, "grpc")
| summarize {
call_count = count(),
error_count = countIf(span.status_code == "error"),
avg_duration_ms = avg(duration) / 1ms
}, by: {span.kind, rpc.service, rpc.method}
| fieldsAdd error_rate_pct = (error_count * 100.0) / call_count
| sort call_count desc
| limit 50

// gRPC status-code coverage: populated vs. not-yet-instrumented.
// A null rpc.grpc.status_code is NOT a healthy call — it means the gRPC-specific code
// was not populated. Check the OneAgent version on the reporting host.
//
// Case-insensitive rpc.system match for the reason given in the previous cell.
// Live-verified 07/30/2026: of 118,380 gRPC spans in one hour, only 11 carried
// rpc.grpc.status_code — so on a real fleet the "not yet instrumented" population is
// the overwhelming majority, and reading null as OK would be badly wrong.
fetch spans, from:-1h
| filter matchesValue(rpc.system, "grpc")
| summarize calls = count(), by: {rpc.grpc.status_code, span.status_code}
| sort calls desc
| limit 50

// Field names corrected 08/12/2026 — pre-1.0 OpenTelemetry database semconv names had been
// used throughout, and every one of them is null on Grail spans. They fail SILENTLY: a filter on a
// non-existent field matches nothing and a summarize groups everything under null, so these cells
// returned empty or single-null-group results without ever erroring.
//   db.operation         -> db.operation.name    (stable; set on 50,379 of 57,295 db spans)
//   db.statement         -> db.query.text        (stable; 33,463)
//   db.mongodb.collection-> db.collection.name   (stable; 6,912)
//   db.name              -> db.namespace         (stable; 57,281)
// Confirm the catalog for your tenant with:
//   fetch dt.semantic_dictionary.fields | filter startsWith(name, "db.") | fields name, stability
// Find all database spans
fetch spans, from:-1h
| filter isNotNull(db.system)
| fields start_time,
dt.service.name,
db.system,
db.namespace,
db.operation.name,
duration
| sort duration desc
| limit 50

// Summarize database usage
fetch spans, from:-1h
| filter isNotNull(db.system)
| summarize {
db_span_count = count(),
avg_duration_ms = avg(duration) / 1ms
}, by: {db.system, db.namespace}
| sort db_span_count desc

// Find spans that have database information
fetch spans, from:-1h
| filter isNotNull(db.system)
| summarize {db_span_count = count()}, by: {db.system, db.namespace}
| sort db_span_count desc

// Confirm the contract for both request-attribute field families
// before writing a filter. Scans zero billable bytes.
fetch dt.semantic_dictionary.fields
| filter contains(name, "request_attribute")
or contains(name, "captured_attribute")
| fields name, stability, type, description
